    const now=Date.now();
    if(liveCommerceSeen[key]&&now-liveCommerceSeen[key]<3500)return;
    setLiveCommerceSeen(s=>({...s,[key]:now}));
    fetch(`${API}/api/v1/vibes/${vibe.id}/commerce-live-seen`,{method:'POST',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({linkId:link.id,sessionId:sessionIdRef.current,playbackMs})}).catch(()=>{});
