  const worksCompareWorkers=liveWorkers.filter(w=>worksCompareKeys.includes(workerSaveKey(w))).slice(0,3);
  const toggleWorksCompare=(worker)=>setWorksCompareKeys(keys=>{const k=workerSaveKey(worker);return keys.includes(k)?keys.filter(x=>x!==k):keys.length>=3?keys:[...keys,k];});
