  async function loadWorksLifecycle(workCode){
    const customerId=currentUser?.id||currentUser?.user_id;
    if(!customerId||!workCode)return null;
    try{
      const endpoints=[
        `${WORKS_API_BASE}/api/works/customer/bookings/${encodeURIComponent(workCode)}/lifecycle?userId=${encodeURIComponent(customerId)}`,
        `${WORKS_API_BASE}/api/works/customer/bookings/${encodeURIComponent(workCode)}/lifecycle-v161c?userId=${encodeURIComponent(customerId)}`
      ];
      for(const endpoint of endpoints){
        const r=await fetch(endpoint,{cache:"no-store"});
        const d=await r.json().catch(()=>({}));
        if(!r.ok)continue;
        const lifecycle=d.lifecycle||{journey:d.journey||null,payments:d.payments||[],completion:d.completion||null,review:d.review||null,cases:d.cases||[],reschedules:d.reschedules||[],actions:d.actions||{}};
        setWorksLifecycleByCode(prev=>({...prev,[workCode]:lifecycle}));
        return lifecycle;
      }
      return null;
    }catch{return null;}
  }

  async function worksCustomerPost(booking,path,payload={}){
    const customerId=currentUser?.id||currentUser?.user_id;
    if(!customerId||!booking?.workCode)return;
    const key=`${path}-${booking.workCode}`;setWorksCustomerAction(key);setWorksCustomerNotice("");
    try{
      const requestOptions={method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({customerUserId:customerId,...payload})};
      const actionUrls=[
        `${WORKS_API_BASE}/api/works/customer/bookings/${encodeURIComponent(booking.workCode)}/${path}`,
        `${WORKS_API_BASE}/api/works/bookings/${encodeURIComponent(booking.workCode)}/${path}`
      ];
      let r=null;
      let d={};
      for(const actionUrl of actionUrls){
        r=await fetch(actionUrl,requestOptions);
        d=await r.json().catch(()=>({}));
        if(r.ok)break;
        if(r.status!==404 && d.message!=="API endpoint not found")break;
      }
      if(!r?.ok)throw new Error(d.message||"HOWDI Works action failed");
      const message=d.message||(
        path==="completion"?"Work completion updated.":
        path==="pay"?"Payment request created.":
        path==="review"?"Review submitted.":
        path==="tip"?"Tip request created.":
        path==="case"?"HOWDI escalation created.":
        "HOWDI Works updated."
      );
      setWorksCustomerNotice(message);
      if(d.lifecycle)setWorksLifecycleByCode(prev=>({...prev,[booking.workCode]:d.lifecycle}));
      if(path==="completion"&&payload.decision==="confirmed"){
        setWorksCustomerBookings(prev=>prev.map(x=>x.workCode===booking.workCode?{...x,stage:"customer_confirmed",status:"completed",completion:{status:"confirmed",note:payload.note||""}}:x));
      }
      setWorksToast({icon:path==="case"?"🎫":path==="review"?"⭐":path==="pay"?"💳":"✅",title:"HOWDI Works updated",message,workCode:booking.workCode});
      window.setTimeout(()=>setWorksToast(null),4500);
      await Promise.all([loadCustomerWorksBookings({silent:true}),loadWorksLifecycle(booking.workCode),loadWorksNotifications()]);
    }catch(error){
      const message=error.message||"HOWDI Works action failed";
      setWorksCustomerNotice(message);
      setWorksToast({icon:"⚠️",title:"Action could not be completed",message,workCode:booking?.workCode||""});
      window.setTimeout(()=>setWorksToast(null),5500);
    }
    finally{setWorksCustomerAction("");}
  }

  async function openWorksReceipt(booking){
    try{
      const lifecycle=await loadWorksLifecycle(booking.workCode)||worksLifecycleByCode[booking.workCode]||{};
      const pay=(lifecycle.payments||[]).find(x=>x.payment_kind==="service")||booking.payment||{};
      const completion=lifecycle.completion||booking.completion||{};
      const review=lifecycle.review||null;
      const amount=Number(lifecycle.quote?.total||booking.budget||0);
      window.alert(`HOWDI WORKS LIFECYCLE\n${booking.workCode}\n${booking.title||""}\nAmount: ₹${amount.toLocaleString("en-IN")}\nPayment: ${pay?.status||"not paid"}\nCompletion: ${completion?.status||"pending"}\nReview: ${review?.rating?review.rating+"★":"not submitted"}`);
    }catch(error){setWorksCustomerNotice(error.message||"Lifecycle unavailable");}
  }

  async function downloadWorksInvoice(booking){
    const customerId=currentUser?.id||currentUser?.user_id;if(!customerId||!booking?.workCode)return;
    setWorksCustomerAction(`invoice-${booking.workCode}`);setWorksCustomerNotice("");
    try{
      const r=await fetch(`${WORKS_API_BASE}/api/works/customer/bookings/${encodeURIComponent(booking.workCode)}/invoice-v161c?userId=${encodeURIComponent(customerId)}`,{cache:"no-store"});
      const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||"Invoice unavailable");
      const x=d.invoice||{};
      const esc=v=>String(v??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
      const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(x.invoiceNumber||booking.workCode)}</title><style>body{font-family:Arial,sans-serif;color:#173c2c;padding:36px;max-width:820px;margin:auto}header{display:flex;justify-content:space-between;border-bottom:2px solid #285f43;padding-bottom:16px}h1{margin:0}.pill{background:#dcfce7;color:#166534;padding:7px 11px;border-radius:999px;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:24px 0}.card{border:1px solid #dfe8e2;border-radius:12px;padding:14px}.total{font-size:24px;font-weight:800;text-align:right;margin-top:24px}small{color:#64748b}</style></head><body><header><div><small>HOWDI WORKS</small><h1>Paid Service Invoice</h1><p>${esc(x.invoiceNumber||"")}</p></div><span class="pill">${esc(x.status||"PAID")}</span></header><div class="grid"><div class="card"><small>WORK CODE</small><b><br>${esc(x.workCode||booking.workCode)}</b></div><div class="card"><small>ISSUED</small><b><br>${esc(x.issuedAt?new Date(x.issuedAt).toLocaleString("en-IN"):"")}</b></div><div class="card"><small>CUSTOMER</small><b><br>${esc(x.customer?.name||"")}</b><br>${esc([x.customer?.city,x.customer?.pincode].filter(Boolean).join(" · "))}</div><div class="card"><small>WORKER</small><b><br>${esc(x.worker?.name||"")}</b><br>${esc(x.worker?.workerCode||"")}</div></div><div class="card"><small>SERVICE</small><h3>${esc(x.service||booking.title||"HOWDI Works service")}</h3><p>Service amount: ₹${Number(x.serviceAmount||0).toLocaleString("en-IN")}</p><p>Tip: ₹${Number(x.tipAmount||0).toLocaleString("en-IN")}</p><p>Payment: ${esc(x.paymentMethod||"")} · ${esc(x.paymentReference||"")}</p></div><div class="total">Total paid: ₹${Number(x.totalPaid||0).toLocaleString("en-IN")}</div><p><small>${esc(x.note||"")}</small></p></body></html>`;
      const blob=new Blob([html],{type:"text/html;charset=utf-8"});const href=URL.createObjectURL(blob);const a=document.createElement("a");a.href=href;a.download=`${x.invoiceNumber||booking.workCode||"HOWDI-WORKS-INVOICE"}.html`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(href);
      setWorksCustomerNotice("Paid invoice downloaded. Open it and use Print → Save as PDF if required.");
    }catch(error){setWorksCustomerNotice(error.message||"Invoice unavailable");}
    finally{setWorksCustomerAction("");}
  }

  async function loadCustomerWorksBookings({silent=false}={}){
    const customerId=currentUser?.id||currentUser?.user_id;
    if(!customerId){
      setWorksCustomerBookings([]);
      setWorksCustomerHistory([]);
      return;
    }
    if(!silent)setWorksCustomerBookingsLoading(true);
    if(!silent)setWorksCustomerBookingsError("");
    try{
      const [bookingResponse,historyResponse]=await Promise.all([
        fetch(`${WORKS_API_BASE}/api/works/customer/bookings?userId=${encodeURIComponent(customerId)}`,{cache:"no-store"}),
        fetch(`${WORKS_API_BASE}/api/works/customer/history?userId=${encodeURIComponent(customerId)}`,{cache:"no-store"})
      ]);
      const data=await bookingResponse.json().catch(()=>({}));
      const historyData=await historyResponse.json().catch(()=>({}));
      if(!bookingResponse.ok)throw new Error(data.message||"Unable to load HOWDI Works bookings");
      const bookingRows=Array.isArray(data.bookings)?data.bookings:[];

      const liveRows=await Promise.all(bookingRows.map(async(item)=>{
        const currentStage=String(item.stage||item.status||"").toLowerCase();
        if(!item.workCode||["rejected","cancelled","closed"].includes(currentStage))return item;
        try{
          const tr=await fetch(`${WORKS_API_BASE}/api/works/track/${encodeURIComponent(item.workCode)}`,{cache:"no-store"});
          const td=await tr.json().catch(()=>({}));
          if(!tr.ok||!td?.tracking)return item;
          const t=td.tracking;
          return {
            ...item,
            stage:t.stage||item.stage,
            pinVerified:t.pinVerified===true,
            workerName:t.worker?.name||item.workerName||item.preferredWorkerName||"",
            workerCode:t.worker?.workerCode||item.workerCode||"",
            workerRating:Number(t.worker?.rating||item.workerRating||0),
            etaMinutes:t.etaMinutes==null?item.etaMinutes:Number(t.etaMinutes),
            lastLocationAt:t.lastLocationAt||item.lastLocationAt||null,
            location:t.location||item.location||null,
            timestamps:{...(item.timestamps||{}),...(t.timestamps||{})}
          };
        }catch{
          return item;
        }
      }));

      const stageRank=(item)=>{
        const s=String(item.stage||item.status||"open").toLowerCase();
        if(["accepted","en_route","arrived","in_progress"].includes(s))return 0;
        if(["offered","open","assigned"].includes(s))return 1;
        if(["completed","customer_confirmed","checked_out","closed"].includes(s))return 2;
        if(s==="cancelled")return 3;
        if(s==="rejected")return 4;
        return 5;
      };
      const sortedRows=[...liveRows].sort((a,b)=>stageRank(a)-stageRank(b)||new Date(b.createdAt||0)-new Date(a.createdAt||0));
      setWorksCustomerBookings(sortedRows);
      sortedRows.slice(0,12).forEach(item=>{ if(item.workCode) loadWorksLifecycle(item.workCode); });

      const apiHistoryRows=historyResponse.ok&&Array.isArray(historyData.history)?historyData.history:[];
      const bookingFallbackHistory=liveRows
        .filter(item=>String(item.stage||item.status||"").toLowerCase()==="rejected")
        .map(item=>({
          id:`booking-rejected-${item.workCode||item.id}`,
          type:"rejected",
          status:"rejected",
          workId:String(item.id||""),
          workCode:item.workCode||"",
          title:item.title||`${item.category||item.serviceName||"HOWDI"} service request`,
          serviceName:item.category||item.serviceName||"",
          city:item.city||"",
          pincode:item.pincode||"",
          budget:Number(item.budget||0),
          scheduleDate:item.scheduleDate||"",
          scheduleTime:item.scheduleTime||"",
          workerName:item.workerName||item.preferredWorkerName||"",
          workerCode:item.workerCode||"",
          reason:item.rejectionReason||"",
          happenedAt:item.rejectionRespondedAt||item.updatedAt||item.createdAt||null
        }));

      const mergedHistory=[...apiHistoryRows];
      for(const item of bookingFallbackHistory){
        if(!mergedHistory.some(h=>h.status==="rejected"&&h.workCode===item.workCode))mergedHistory.push(item);
      }
      setWorksCustomerHistory(mergedHistory.sort((a,b)=>new Date(b.happenedAt||0)-new Date(a.happenedAt||0)));
      loadWorksNotifications();
    }catch(error){
      setWorksCustomerBookingsError(error.message||"Unable to load HOWDI Works bookings");
    }finally{
      if(!silent)setWorksCustomerBookingsLoading(false);
    }
  }

  async function verifyWorksJobPin(booking){
    const customerId=currentUser?.id||currentUser?.user_id;
    if(!customerId||!booking?.workCode||!booking?.jobPin)return;
    setWorksCustomerAction(`verify-${booking.workCode}`);
    setWorksCustomerNotice("");
    try{
      const response=await fetch(`${WORKS_API_BASE}/api/works/bookings/${encodeURIComponent(booking.workCode)}/verify-pin`,{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({customerUserId:customerId,pin:String(booking.jobPin)})
      });
      const data=await response.json().catch(()=>({}));
      if(!response.ok)throw new Error(data.message||"Unable to verify Job PIN");
      setWorksCustomerNotice("Worker verified. Work can now start safely.");
      await loadCustomerWorksBookings();
    }catch(error){
      setWorksCustomerNotice(error.message||"Unable to verify Job PIN");
    }finally{
      setWorksCustomerAction("");
    }
  }

  async function refreshWorksBooking(booking){
    setWorksCustomerAction(`refresh-${booking.workCode}`);
    setWorksCustomerNotice("");
    try{
      await loadCustomerWorksBookings();
    }finally{
      setWorksCustomerAction("");
    }
  }

  async function openWorksProfile(worker){
    setWorksProfileOpen(true);
    setWorksProfileLoading(false);
    setWorksProfileError("");
    setWorksProfile({
      ...worker,
      primaryService:worker.primaryService||worker.service||"",
      services:Array.isArray(worker.services)&&worker.services.length
        ? worker.services
        : (worker.service?[{id:worker.service,name:worker.service,icon:worker.serviceIcon||"🛠️",primary:true}]:[])
    });
  }
  async function loadCustomerWorks(){
    try{
      const [serviceResponse,workerResponse,homeResponse]=await Promise.all([
        fetch(`${WORKS_API_BASE}/api/works/services`),
        fetch(`${WORKS_API_BASE}/api/works/workers`),
        fetch(`${WORKS_API_BASE}/api/works/home`)
      ]);
      if(!serviceResponse.ok||!workerResponse.ok) throw new Error("Works API unavailable");
      const serviceData=await serviceResponse.json();
      const workerData=await workerResponse.json();
      const homeData=homeResponse.ok?await homeResponse.json():null;
      if(homeData?.home)setWorksHomeData(homeData.home);
      setLiveWorkCategories((serviceData.services||[]).map(service=>({
        id:service.id,icon:service.icon||"🛠️",name:service.name,eligibleWorkers:Number(service.eligibleWorkers||0)
      })));
      setLiveWorkers(workerData.workers||[]);
      setWorksLiveError("");
    }catch(error){
      setWorksLiveError(error.message||"Works API unavailable");
    }
  }
