  const shopCategoryOptions=["All",...Array.from(new Set(products.map(p=>String(p.category||"Handmade")).filter(Boolean)))];
  const shopSubcategoryOptions=["All",...Array.from(new Set(products.map(p=>String(p.subcategory||p.productType||"")).filter(Boolean)))];
  const shopMaterialOptions=["All",...Array.from(new Set(products.map(p=>String(p.material||"")).filter(Boolean))).slice(0,8)];
  const shopColorOptions=["All",...Array.from(new Set(products.flatMap(p=>Array.isArray(p.colors)?p.colors:[]).map(String).filter(Boolean))).slice(0,10)];
  const shopSizeOptions=["All",...Array.from(new Set(products.flatMap(p=>Array.isArray(p.sizes)?p.sizes:[]).map(String).filter(Boolean))).slice(0,10)];
  const shopNumericPrice=(p)=>{
    const direct=Number(p?.numericPrice);
    if(Number.isFinite(direct)&&direct>0)return direct;
    return Number(String(p?.price||"0").replace(/[^0-9.]/g,""))||0;
  };
  const shopFilteredProducts=products
    .filter((product)=>{
      const query=shopSearch.trim().toLowerCase();
      const hay=`${product.name||""} ${product.shop||""} ${product.category||""} ${product.subcategory||""} ${product.productType||""} ${product.artisan||""} ${product.material||""}`.toLowerCase();
      if(query&&!hay.includes(query))return false;
      if(shopCategoryFilter!=="All"&&String(product.category||"")!==shopCategoryFilter)return false;
      if(shopSubcategoryFilter!=="All"&&String(product.subcategory||product.productType||"")!==shopSubcategoryFilter)return false;
      if(shopMaterialFilter!=="All"&&!String(product.material||"").toLowerCase().includes(shopMaterialFilter.toLowerCase()))return false;
      if(shopColorFilter!=="All"&&!(Array.isArray(product.colors)&&product.colors.map(String).includes(shopColorFilter)))return false;
      if(shopSizeFilter!=="All"&&!(Array.isArray(product.sizes)&&product.sizes.map(String).includes(shopSizeFilter)))return false;
      if(shopAvailabilityFilter==="In Stock"&&Number(product.stock||0)<=0)return false;
      if(shopAvailabilityFilter==="Made to Order"&&!String(product.badges||"").toLowerCase().includes("made to order"))return false;
      const price=shopNumericPrice(product);
      if(shopPriceFilter==="Under ₹500"&&price>=500)return false;
      if(shopPriceFilter==="₹500–₹999"&&(price<500||price>=1000))return false;
      if(shopPriceFilter==="₹1,000–₹1,999"&&(price<1000||price>=2000))return false;
      if(shopPriceFilter==="₹2,000+"&&price<2000)return false;
      return true;
    })
    .sort((a,b)=>{
      if(shopSort==="Price: Low to High")return shopNumericPrice(a)-shopNumericPrice(b);
      if(shopSort==="Price: High to Low")return shopNumericPrice(b)-shopNumericPrice(a);
      if(shopSort==="Rating")return Number(b.rating||0)-Number(a.rating||0);
      if(shopSort==="Newest")return String(b.id||b.name||"").localeCompare(String(a.id||a.name||""));
      return Number(b.reviews||0)-Number(a.reviews||0);
    });
