  const getReferralLink = () => {
    if (!referralData.referral_code) return "";
    return `${window.location.origin}/?ref=${encodeURIComponent(referralData.referral_code)}`;
  };

  const recordReferralShare = async (channel = "COPY") => {
    if (!currentUser?.id) return;
    try {
      await fetch(
        `http://localhost:5000/api/referrals/user/${encodeURIComponent(currentUser.id)}/share`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ channel }),
        }
      );
      await loadReferralData();
    } catch (error) {
      console.error("Referral share tracking error:", error);
    }
  };

  const copyReferralLink = async () => {
    const link = getReferralLink();
    if (!link) {
      setReferralNotice("Your referral link is still being prepared.");
      return;
    }

    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(link);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = link;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand("copy");
        textarea.remove();
      }
      setReferralNotice("Referral link copied. Share it with someone you invite. 🔗");
      await recordReferralShare("COPY");
    } catch {
      setReferralNotice("Unable to copy automatically. Please copy the link manually.");
    }
  };

  const shareReferralLink = async () => {
    const link = getReferralLink();
    if (!link) {
      setReferralNotice("Your referral link is still being prepared.");
      return;
    }

    try {
      if (navigator.share) {
        await navigator.share({
          title: "Join HOWDI",
          text: "Join HOWDI with my invitation link.",
          url: link,
        });
        setReferralNotice("Invitation shared successfully. 🚀");
        await recordReferralShare("NATIVE_SHARE");
      } else {
        await copyReferralLink();
      }
    } catch (error) {
      if (error?.name !== "AbortError") {
        setReferralNotice("Sharing was not completed.");
      }
    }
  };

  const loadWalletData = async () => {
    if (!currentUser?.id) return;
    setWalletLoading(true);
    try {
      const response = await fetch(`http://localhost:5000/api/wallet/user/${encodeURIComponent(currentUser.id)}`, { cache: "no-store" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.status !== "success") throw new Error(data.message || "Unable to load wallet.");
      setWalletBalance(Number(data.wallet?.balance || 0));
      setWalletTransactions(Array.isArray(data.wallet?.transactions) ? data.wallet.transactions.map((x)=>({
        id:x.id,title:x.title,type:String(x.transaction_type||"CREDIT").toLowerCase().includes("debit")?"debit":"credit",amount:Number(x.amount||0),date:new Date(x.created_at).toLocaleString("en-IN")
      })) : []);
      setCashbackStats({total:Number(data.cashback?.total||0),pending:Number(data.cashback?.pending||0),available:Number(data.cashback?.available||0)});
      setCashbackHistory(Array.isArray(data.cashback?.history) ? data.cashback.history.map((x) => ({...x, date: formatCommunicationDate(x.created_at)})) : []);
      setRewardPoints(Number(data.rewards?.points||0));
      setWalletRewards(Array.isArray(data.rewards?.history) ? data.rewards.history.map((x)=>({id:x.id,title:x.title,points:Number(x.points||0),date:new Date(x.created_at).toLocaleString("en-IN")})) : []);
      setWalletMessage("");
    } catch (e) {
      console.error("Wallet load error:", e);
      setWalletMessage(e.message || "Unable to load wallet and cashback. Please try again.");
    } finally { setWalletLoading(false); }
  };

