  const formatCommunicationDate = (value) => {
    if (!value) return "";
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" });
  };

  const loadCommunications = async () => {
    if (!currentUser?.id) return;
    setCommunicationsLoading(true);
    try {
      const response = await fetch(`http://localhost:5000/api/communications/user/${encodeURIComponent(currentUser.id)}`, { cache: "no-store" });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.status !== "success") throw new Error(data.message || "Unable to load messages.");
      setMessages((data.messages || []).map((x) => ({
        id:x.id, type:x.message_type || "account", icon:x.icon || "✉️", title:x.title,
        text:x.message, recipient:x.recipient, date:formatCommunicationDate(x.created_at),
        unread:!x.is_read, direction:x.direction
      })));
      setNotifications((data.notifications || []).map((x) => ({
        id:x.id, type:x.notification_type || "account", icon:x.icon || "🔔", title:x.title,
        text:x.message, time:formatCommunicationDate(x.created_at), unread:!x.is_read
      })));
    } catch (e) {
      console.error("Communications load error:", e);
    } finally { setCommunicationsLoading(false); }
  };

  useEffect(() => { loadCommunications(); }, [currentUser?.id]);

