  const formatConnectDate = (value) => {
    if (!value) return "";
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "";
    const diff = Date.now() - date.getTime();
    if (diff >= 0 && diff < 60 * 1000) return "Just now";
    if (diff >= 0 && diff < 60 * 60 * 1000) return `${Math.max(1, Math.floor(diff / 60000))}m ago`;
    if (diff >= 0 && diff < 24 * 60 * 60 * 1000) return `${Math.max(1, Math.floor(diff / 3600000))}h ago`;
    return date.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  };

  const loadConnectFeed = async () => {
    setConnectLoading(true);
    try {
      const params=new URLSearchParams();
      if(currentUser?.id)params.set("userId",String(currentUser.id));
      if(connectPostFeedType)params.set("type",connectPostFeedType);
      if(connectPostFeedKnowledge)params.set("knowledge",connectPostFeedKnowledge);
      if(connectPostFeedAudience)params.set("audience",connectPostFeedAudience);
      const response = await fetch(`${SHOP_API_BASE}/api/connect/feed?${params.toString()}`, {
        cache: "no-store",
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok || data.status !== "success") {
        throw new Error(data.message || "Unable to load HOWDI Connect.");
      }
      setConnectPosts(data.posts || []);
    } catch (error) {
      console.error("HOWDI Connect load error:", error);
      setConnectNotice(error.message || "Unable to load community posts.");
    } finally {
      setConnectLoading(false);
    }
  };

