  const flipConnectLiveCamera=async()=>{
    const next=connectLiveFacingMode==="user"?"environment":"user";setConnectLiveFacingMode(next);
    try{
      const current=connectRealtimeStreamRef.current;if(!current)return;
      const newStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:next}},audio:false});
      const newTrack=newStream.getVideoTracks()[0],old=current.getVideoTracks()[0];
      if(old){current.removeTrack(old);old.stop();}
      current.addTrack(newTrack);
      for(const pc of connectRealtimePeersRef.current.values()){
        const sender=pc.getSenders().find(s=>s.track?.kind==="video");if(sender)await sender.replaceTrack(newTrack);
      }
      if(connectRealtimeLocalVideoRef.current)connectRealtimeLocalVideoRef.current.srcObject=current;
    }catch(e){setConnectNotice("Camera flip is unavailable on this device/browser.");}
  };

  const toggleConnectLiveScreenShare=async()=>{
    try{
      if(connectLiveScreenSharing){
        setConnectNotice("Stop sharing from the browser sharing bar, then return to camera.");return;
      }
      if(!navigator.mediaDevices?.getDisplayMedia)return setConnectNotice("Screen sharing is not supported by this browser.");
      const display=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});
      const track=display.getVideoTracks()[0];
      for(const pc of connectRealtimePeersRef.current.values()){const sender=pc.getSenders().find(s=>s.track?.kind==="video");if(sender)await sender.replaceTrack(track);}
      if(connectRealtimeLocalVideoRef.current)connectRealtimeLocalVideoRef.current.srcObject=display;
      setConnectLiveScreenSharing(true);
      track.onended=()=>{setConnectLiveScreenSharing(false);const cam=connectRealtimeStreamRef.current?.getVideoTracks?.()[0];if(cam){for(const pc of connectRealtimePeersRef.current.values()){const sender=pc.getSenders().find(s=>s.track?.kind==="video");if(sender)sender.replaceTrack(cam).catch(()=>{});}if(connectRealtimeLocalVideoRef.current)connectRealtimeLocalVideoRef.current.srcObject=connectRealtimeStreamRef.current;}};
    }catch(e){setConnectNotice("Screen sharing was cancelled or unavailable.");}
  };

