  const connectProfileCategoryLabel=(v)=>String(v||"GENERAL").replaceAll("_"," ").replace(/\b\w/g,c=>c.toUpperCase());
  const connectPresenceLabel=(p)=>{
    if(!p?.activity_visible||p?.presence_status==="HIDDEN")return "Activity hidden";
    if(p?.is_live_now)return "🔴 Live now";
    if(p?.presence_status==="ONLINE")return "🟢 Active now";
    if(p?.presence_status==="BUSY")return "🔴 Busy";
    if(p?.presence_status==="AWAY")return "🟡 Away";
    if(p?.last_seen_at){
      const mins=Math.max(0,Math.floor((Date.now()-new Date(p.last_seen_at).getTime())/60000));
      if(mins<1)return "Active just now";
      if(mins<60)return `Last seen ${mins}m ago`;
      if(mins<1440)return `Last seen ${Math.floor(mins/60)}h ago`;
      return `Last seen ${Math.floor(mins/1440)}d ago`;
    }
    return "Offline";
  };

