  useEffect(()=>{
    const userId=Number(currentUser?.id||currentUser?.user_id||0);
    if(!userId)return;
    let active=true;
    const check=async()=>{
      try{
        const d=await connectApi(`/api/connect/reminders/due?userId=${userId}`);
        if(!active)return;
        if(Array.isArray(d.notifications)&&d.notifications.length){
          setConnectNotifications(prev=>{
            const ids=new Set(prev.map(n=>String(n.id)));
            return [...d.notifications.filter(n=>!ids.has(String(n.id))),...prev].slice(0,100);
          });
        }
      }catch{}
    };
    check();
    const timer=window.setInterval(check,60000);
    return()=>{active=false;window.clearInterval(timer);};
  },[currentUser?.id,currentUser?.user_id]);



  const connectSpaceCountdown=(value)=>{
    if(!value)return "";
    const diff=new Date(value).getTime()-connectSpaceClock;
    if(!Number.isFinite(diff))return "";
    if(diff<=0)return "Starting soon";
    const mins=Math.floor(diff/60000);
    if(mins<60)return `Starts in ${Math.max(1,mins)}m`;
    const hrs=Math.floor(mins/60),rem=mins%60;
    if(hrs<24)return `Starts in ${hrs}h${rem?` ${rem}m`:""}`;
    const days=Math.floor(hrs/24);
    return `Starts in ${days}d ${hrs%24}h`;
  };

