      const d=await connectApi(`/api/connect/stories/${story.id}/share`,{method:"POST",body:JSON.stringify({shareKey:connectViewerKey()})});
      updateConnectStoryLocal(story.id,{share_count:Number(d.share_count||0)});
      const link=`${window.location.origin}${window.location.pathname}#connect-story-${story.id}`;
      if(navigator.share){await navigator.share({title:`${story.full_name||"HOWDI"} on HOWDI`,text:story.content||"HOWDI Story",url:link});}
