  const nextDateForDay=(day)=>{
    const now=new Date();
    const d=new Date(now.getFullYear(),now.getMonth(),now.getDate());
    let diff=(Number(day)-d.getDay()+7)%7;
    if(diff===0)diff=7;
    d.setDate(d.getDate()+diff);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  };
  useEffect(()=>{
    if(!activeClassroom||classroomEnded)return;
    const timer=setInterval(()=>setClassroomClock(Date.now()),1000);
    return()=>clearInterval(timer);
  },[activeClassroom?.id,classroomEnded]);

  useEffect(()=>{
    if(!activeClassroom?.id||!currentUser?.id||classroomEnded)return;
    let stopped=false;
    const sync=async()=>{
      try{
        const r=await learningFetch(`http://localhost:5000/api/learning/live/bookings/${activeClassroom.id}/classroom?user_id=${currentUser.id}`,{cache:"no-store"});
        const d=await r.json().catch(()=>({}));
        if(stopped||!r.ok||d.status!=="success")return;
        const latest={...activeClassroom,...d.booking,classroom:d.classroom};
        const ended=Boolean(d.classroom?.is_ended)||['COMPLETED','NO_SHOW','CANCELLED'].includes(String(d.booking?.status||''))||String(d.booking?.session_status||'')==='ENDED';
        if(ended){
          setActiveClassroom(latest);
          setClassroomEvents(d.events||[]);
          setClassroomEnded(true);
          stopLearnerRTC();
          setClassroomClock(d.booking?.session_ended_at?new Date(d.booking.session_ended_at).getTime():Date.now());
          setLiveNotice(d.booking?.status==='COMPLETED'?'Teacher ended the class. Attendance is being finalized by HOWDI.':'This classroom session has ended.');
        }
      }catch{}
    };
    sync();
    const ms=Math.max(2000,Number(activeClassroom?.classroom?.sync_seconds||3)*1000);
    const timer=setInterval(sync,ms);
    return()=>{stopped=true;clearInterval(timer);};
  },[activeClassroom?.id,currentUser?.id,classroomEnded]);

  const classroomDuration=(booking)=>{
    if(!booking?.joined_at)return "00:00";
    const end=booking.session_ended_at?new Date(booking.session_ended_at).getTime():(booking.left_at?new Date(booking.left_at).getTime():classroomClock);
    const secs=Math.max(0,Math.floor((end-new Date(booking.joined_at).getTime())/1000));
    const mm=String(Math.floor(secs/60)).padStart(2,"0");
    const ss=String(secs%60).padStart(2,"0");
    return `${mm}:${ss}`;
  };

  useEffect(()=>{
    if(activeClassroom&&localVideoRef.current&&rtcLocalStreamRef.current){
      localVideoRef.current.srcObject=rtcLocalStreamRef.current;
      localVideoRef.current.play?.().catch(()=>{});
    }
  },[activeClassroom?.id]);

  const rtcConfig={iceServers:[{urls:"stun:stun.l.google.com:19302"},{urls:"stun:stun1.l.google.com:19302"}]};

  const stopLearnerRTC=()=>{
    if(rtcPollRef.current){clearInterval(rtcPollRef.current);rtcPollRef.current=null;}if(rtcStatsRef.current){clearInterval(rtcStatsRef.current);rtcStatsRef.current=null;}
    if(rtcPeerRef.current){try{rtcPeerRef.current.close();}catch{}rtcPeerRef.current=null;}learnerPendingIceRef.current=[];
    if(rtcLocalStreamRef.current){rtcLocalStreamRef.current.getTracks().forEach(t=>t.stop());rtcLocalStreamRef.current=null;}
    if(localVideoRef.current)localVideoRef.current.srcObject=null;
    if(remoteVideoRef.current)remoteVideoRef.current.srcObject=null;
    setRtcState("idle");
  };

  const sendLearnerSignal=async(bookingId,signal_type,payload={})=>{
    const r=await learningFetch(`http://localhost:5000/api/learning/live/bookings/${bookingId}/signals`,{
      method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({sender_role:"LEARNER",user_id:currentUser.id,signal_type,payload})
    });
    const d=await r.json().catch(()=>({}));
    if(!r.ok||d.status!=="success")throw new Error(d.message||"Classroom connection error");
  };

  const pollLearnerSignals=async(bookingId)=>{
    try{
      const r=await learningFetch(`http://localhost:5000/api/learning/live/bookings/${bookingId}/signals?receiver_role=LEARNER&user_id=${currentUser.id}`,{cache:"no-store"});
      const d=await r.json().catch(()=>({}));
      if(!r.ok||d.status!=="success")return;
      for(const s of d.signals||[]){
        const pc=rtcPeerRef.current;
        if(!pc)continue;
        if(s.signal_type==="OFFER"){
          await pc.setRemoteDescription(new RTCSessionDescription(s.payload));
          const queued=[...learnerPendingIceRef.current];
          learnerPendingIceRef.current=[];
          for(const ice of queued){try{await pc.addIceCandidate(new RTCIceCandidate(ice));}catch{}}
          const answer=await pc.createAnswer();
          await pc.setLocalDescription(answer);
          await sendLearnerSignal(bookingId,"ANSWER",pc.localDescription);
          setRtcState("connecting");
        }else if(s.signal_type==="ICE"&&s.payload?.candidate){
          if(pc.remoteDescription){try{await pc.addIceCandidate(new RTCIceCandidate(s.payload));}catch{}}
          else learnerPendingIceRef.current.push(s.payload);
        }else if(s.signal_type==="HANGUP"){
          stopLearnerRTC();
          setRtcState("ended");
        }
      }
    }catch{}
  };

  const loadClassMessages=async(bookingId)=>{
    try{
      const r=await learningFetch(`http://localhost:5000/api/learning/live/bookings/${bookingId}/messages?role=LEARNER&user_id=${currentUser.id}`,{cache:"no-store"});
      const d=await r.json().catch(()=>({}));
      if(r.ok&&d.status==="success")setClassMessages(d.messages||[]);
    }catch{}
  };
