      const data=await response.json().catch(()=>({}));
      if(!response.ok||data.status!=="success")throw new Error(data.message||"Unable to open this course.");
      setCoursePlayer(data);
      const lessons=(data.modules||[]).flatMap(m=>(m.lessons||[]).map(l=>({...l,module_title:m.title,module_id:m.id})));
      const next=lessons.find(l=>String(l.id)===String(data.next_lesson?.id))||lessons[0]||null;
      setActiveLesson(next);
