  const evidenceFileToDataUrl=(file)=>new Promise((resolve,reject)=>{
    if(!file)return resolve(null);
    if(file.size>8*1024*1024)return reject(new Error("Evidence file must be 8 MB or smaller."));
    const reader=new FileReader();
    reader.onload=()=>resolve({name:file.name,type:file.type,size:file.size,dataUrl:String(reader.result||"")});
    reader.onerror=()=>reject(new Error("Unable to read evidence file."));
    reader.readAsDataURL(file);
  });
