      const subscription = data.subscription || {};
      setSubscriptionPlan(subscription.plan_code || "free");
      setSubscriptionBilling(subscription.billing_cycle || "monthly");
      setSubscriptionAutoRenew(subscription.auto_renew !== false);
      setSubscriptionPayment(subscription.payment_method_id ? String(subscription.payment_method_id) : "");
