  const formatCommentTime = (value) => {
    const date = new Date(value);
    const diff = Date.now() - date.getTime();
    const minutes = Math.max(1, Math.floor(diff / 60000));
    if (minutes < 60) return `${minutes}m ago`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
  };

  const searchMentionUsers = async (query) => {
    const term = String(query || "").replace(/^@/, "").trim().toLowerCase();

    setMentionOpen(true);
    setMentionLoading(true);
    setCommentNotice("");

    // Always keep a local fallback so the @ picker still opens beautifully
    // while the backend is restarting or a network request fails.
    const commentUsers = getCommentsForSelectedProduct().map((comment) => ({
      id: comment.user_id || comment.id,
      full_name: comment.name || "HOWDI user",
      howdi_id: comment.howdi_id || "",
      role: "customer",
    }));

    const localUsers = [
      currentUser ? {
        id: currentUser.id || "current-user",
        full_name: currentUser.full_name || currentUser.name || "My HOWDI account",
        howdi_id: currentUser.howdi_id || "",
        role: currentUser.role || "customer",
      } : null,
      ...commentUsers,
      { id: "howdi-team", full_name: "HOWDI Team", howdi_id: "@howdi", role: "team" },
    ].filter(Boolean);

    const uniqueLocalUsers = Array.from(
      new Map(
        localUsers.map((user) => [
          String(user.id || user.howdi_id || user.full_name).toLowerCase(),
          user,
        ])
      ).values()
    );

    const filterUsers = (users) => users.filter((user) => {
      if (!term) return true;
      const haystack = [
        user.full_name,
        user.name,
        user.howdi_id,
        user.email,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(term);
    });

    try {
      let backendUsers = [];
      let lastError = "";

      for (const endpoint of [
        `http://localhost:5000/api/users/search?q=${encodeURIComponent(term)}`,
        `http://localhost:5000/api/users/mention-search?q=${encodeURIComponent(term)}`,
      ]) {
        try {
          const response = await fetch(endpoint, { cache: "no-store" });
          const data = await response.json().catch(() => ({}));

          if (response.ok && data.status === "success") {
            backendUsers = Array.isArray(data.users) ? data.users : [];
            break;
          }

          lastError = data.message || `User search returned ${response.status}`;
        } catch (error) {
          lastError = error?.message || "Unable to connect to the backend.";
        }
      }

      const merged = Array.from(
        new Map(
          [...backendUsers, ...uniqueLocalUsers].map((user) => [
            String(user.id || user.howdi_id || user.full_name).toLowerCase(),
            user,
          ])
        ).values()
      );

      const matches = filterUsers(merged).slice(0, 12);
      setMentionUsers(matches);

      if (!matches.length && term) {
        setCommentNotice(`No HOWDI user found for "${term}".`);
      } else if (lastError && matches.length) {
        // Keep the UI usable without showing a scary error when local matches exist.
        setCommentNotice("");
      }
    } finally {
      setMentionLoading(false);
    }
  };

  const handleCommentDraftChange = (value) => {
    setCommentDraft(value);

    // The active @ mention must be the last word currently being typed.
    const match = value.match(/(?:^|\s)@([^\s@]*)$/);

    if (match) {
      searchMentionUsers(match[1]);
    } else {
      setMentionOpen(false);
      setMentionUsers([]);
    }
  };

  const selectMentionUser = (user) => {
    const visibleName =
      user?.full_name ||
      user?.name ||
      String(user?.howdi_id || "HOWDI user").replace(/^@/, "");

    const label = String(visibleName).replace(/\s+/g, " ").trim();

    setCommentDraft((current) =>
      current.replace(/@([^\s@]*)$/, `@${label} `)
    );

    setMentionOpen(false);
    setMentionUsers([]);
    setCommentNotice(`Tagged ${label} ✓`);
  };

  const submitProductComment = () => {
    const text = commentDraft.trim();

    if (!currentUser) {
      openLogin();
      setCommentNotice("Please login to join the discussion.");
      return;
    }

    if (!text) {
      setCommentNotice("Write a comment first.");
      return;
    }

    const key = getProductCommentKey(selectedProduct);

    const comment = {
      id: `comment-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      user_id: currentUser.id,
      name: currentUser.full_name || currentUser.name || "HOWDI customer",
      howdi_id: currentUser.howdi_id || "",
      text,
      created_at: new Date().toISOString(),
      likes: 0,
      replies: [],
    };

    setProductComments((current) => ({
      ...current,
      [key]: [comment, ...(Array.isArray(current[key]) ? current[key] : [])],
    }));

    setCommentDraft("");
    setMentionOpen(false);
    setMentionUsers([]);
    setCommentNotice("Comment posted ✓");
  };

  const toggleCommentLike = (commentId) => {
    const key = getProductCommentKey(selectedProduct);
    const likeKey = `${key}:${commentId}`;

    setLikedCommentIds((currentLikes) => {
      const alreadyLiked = currentLikes.includes(likeKey);
      const nextLikes = alreadyLiked
        ? currentLikes.filter((item) => item !== likeKey)
        : [...currentLikes, likeKey];

      setProductComments((current) => {
        const base = Array.isArray(current[key])
          ? current[key]
          : getCommentsForSelectedProduct();

        return {
          ...current,
          [key]: base.map((comment) =>
            comment.id === commentId
              ? {
                  ...comment,
                  likes: Math.max(
                    0,
                    Number(comment.likes || 0) + (alreadyLiked ? -1 : 1)
                  ),
                }
              : comment
          ),
        };
      });

      setCommentNotice(alreadyLiked ? "Like removed." : "Comment liked ❤️");
      return nextLikes;
    });
  };

  const submitCommentReply = (commentId) => {
    const text = replyDraft.trim();

    if (!currentUser) {
      openLogin();
      return;
    }

    if (!text) return;

    const key = getProductCommentKey(selectedProduct);

    const reply = {
      id: `reply-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      user_id: currentUser.id,
      name: currentUser.full_name || currentUser.name || "HOWDI customer",
      howdi_id: currentUser.howdi_id || "",
      text,
      created_at: new Date().toISOString(),
    };

    setProductComments((current) => {
      const base = Array.isArray(current[key])
        ? current[key]
        : getCommentsForSelectedProduct();

      return {
        ...current,
        [key]: base.map((comment) =>
          comment.id === commentId
            ? {
                ...comment,
                replies: [
                  ...(Array.isArray(comment.replies) ? comment.replies : []),
                  reply,
                ],
              }
            : comment
        ),
      };
    });

    setReplyDraft("");
    setReplyingToCommentId("");
  };

  const getSelectedProductShareData = () => {
    if (!selectedProduct) return null;

    const productLink =
      `${window.location.origin}${window.location.pathname}` +
      `#product-${encodeURIComponent(
        selectedProduct.id ??
        selectedProduct.product_id ??
        selectedProduct._id ??
        selectedProduct.name
      )}`;

    const shareText =
      `Check out ${selectedProduct.name} (${selectedProduct.price}) on HOWDI Handmade Marketplace.`;

    return {
      productLink,
      shareText,
      encodedLink: encodeURIComponent(productLink),
      encodedText: encodeURIComponent(shareText),
    };
  };

  const shareSelectedProduct = async () => {
    const shareData = getSelectedProductShareData();
    if (!shareData || !selectedProduct) return;

    try {
      if (navigator.share) {
        await navigator.share({
          title: selectedProduct.name,
          text: shareData.shareText,
          url: shareData.productLink,
        });
      } else if (navigator.clipboard) {
        await navigator.clipboard.writeText(shareData.productLink);
        setShareMessage("Product link copied ✓");
      } else {
        setShareMessage("Share this product from your browser");
      }
    } catch {
      setShareMessage("");
    }
  };



  const stopFitCamera = () => {
    if (fitCameraStream) {
      fitCameraStream.getTracks().forEach((track) => track.stop());
    }
    if (fitVideoRef.current) fitVideoRef.current.srcObject = null;
    setFitCameraStream(null);
  };

  const startFitCamera = async () => {
    setFitCameraMessage("");
    if (!navigator.mediaDevices?.getUserMedia) {
      setFitCameraMessage("Camera access is not supported by this browser. You can still enter measurements manually.");
      return;
    }
    try {
      stopFitCamera();
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" }, audio: false });
      setFitCameraStream(stream);
      window.setTimeout(() => {
        if (fitVideoRef.current) {
          fitVideoRef.current.srcObject = stream;
          fitVideoRef.current.play().catch(() => {});
        }
      }, 0);
    } catch {
      setFitCameraMessage("Camera permission was not granted. Enter your measurements manually for the most reliable fit.");
    }
  };

  const captureFitPhoto = () => {
    const video = fitVideoRef.current;
    if (!video || !video.videoWidth) {
      setFitCameraMessage("Start the camera first, then click Capture photo.");
      return;
    }
    setFitCaptureAllowed(false);
    setFitCaptureConsentOpen(true);
  };

  const confirmFitPhotoCapture = () => {
    const video = fitVideoRef.current;
    const canvas = fitCanvasRef.current;
    if (!fitCaptureAllowed) {
      setFitCameraMessage("Please select “I Allow Photo Capture” before continuing.");
      return;
    }
    if (!video || !canvas || !video.videoWidth) {
      setFitCameraMessage("Please start the camera again before capturing.");
      setFitCaptureConsentOpen(false);
      return;
    }

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const context = canvas.getContext("2d");
    if (!context) {
      setFitCameraMessage("Photo capture is unavailable in this browser.");
      setFitCaptureConsentOpen(false);
      return;
    }

    context.drawImage(video, 0, 0, canvas.width, canvas.height);
    setFitPhoto(canvas.toDataURL("image/jpeg", 0.82));
    setFitCameraMessage("🔒 Photo captured with your permission. This demo does not upload or share it.");
    setFitCaptureConsentOpen(false);
    setFitCaptureAllowed(false);
    stopFitCamera();
  };

  const calculateFitSize = () => {
    const bust = Number(fitMeasurements.bust);
    const waist = Number(fitMeasurements.waist);
    const hip = Number(fitMeasurements.hip);
    if (![bust, waist, hip].every((value) => value > 0)) {
      setFitSizeResult("Enter bust, waist and hip measurements in inches to calculate a size.");
      return;
    }
    const chart = [
      { size: "XS", bust: 32, waist: 26, hip: 35 },
      { size: "S", bust: 34, waist: 28, hip: 37 },
      { size: "M", bust: 36, waist: 30, hip: 39 },
      { size: "L", bust: 38, waist: 32, hip: 41 },
      { size: "XL", bust: 40, waist: 34, hip: 43 },
      { size: "XXL", bust: 42, waist: 36, hip: 45 },
    ];
    const closest = chart.reduce((best, row) => {
      const score = Math.abs(bust - row.bust) + Math.abs(waist - row.waist) + Math.abs(hip - row.hip);
      return !best || score < best.score ? { ...row, score } : best;
    }, null);
    const beyond = bust > 42 || waist > 36 || hip > 45;
    const recommendation = beyond ? "Custom fit recommended — your measurements are outside the standard chart." : `Suggested size: ${closest.size}. We recommend confirming the maker's size chart before ordering.`;
    setFitSizeResult(recommendation);
    setCustomMeasurements(`Height: ${fitMeasurements.height || "—"} in, Bust: ${fitMeasurements.bust} in, Waist: ${fitMeasurements.waist} in, Hip: ${fitMeasurements.hip} in`);
    if (!beyond && selectedProduct?.sizes?.includes(closest.size)) setSelectedProductSize(closest.size);
    if (beyond && selectedProduct?.sizes?.includes("Custom")) setSelectedProductSize("Custom");
  };

  const openFitStudio = () => {
    setFitCaptureConsentOpen(false);
    setFitCaptureAllowed(false);
    setFitStudioOpen(true);
    setFitCameraMessage("");
    setFitSizeResult("");
  };

  const closeFitStudio = () => {
    stopFitCamera();
    setFitStudioOpen(false);
  };

  useEffect(() => {
    if (!fitStudioOpen) return undefined;
    const timer = window.setInterval(() => setFitPreviewRotation((value) => (value + 3) % 360), 80);
    return () => window.clearInterval(timer);
  }, [fitStudioOpen]);

  useEffect(() => () => {
    if (fitCameraStream) fitCameraStream.getTracks().forEach((track) => track.stop());
  }, [fitCameraStream]);

  const getReviewList = () => {
    const reviews = [...(selectedProduct?.recentReviews || [])];
    if (reviewFilter === "helpful") return reviews.sort((a, b) => (b.helpful || 0) - (a.helpful || 0));
    if (reviewFilter === "photos") return reviews.filter((review) => review.photo);
    return reviews;
  };

  const addSelectedProductToCart = () => {
    if (!selectedProduct) return;
    if (selectedProductSize === "Custom" && !customMeasurements.trim() && !fitSizeResult) {
      setProductDetailOpen(true);
      setCartNotice("Please add custom measurements or use Custom Fit Studio before adding this item.");
      return;
    }
    const fitMeasurementText = Object.entries(fitMeasurements)
      .filter(([, value]) => String(value || "").trim())
      .map(([key, value]) => `${key}: ${value} in`)
      .join(", ");
    const configuredProduct = {
      ...selectedProduct,
      selectedSize: selectedProductSize,
      selectedColor: selectedProductColor,
      selectedVariantId:selectedLiveVariant?.id||null,
      selectedVariantSku:selectedLiveVariant?.sku||selectedProduct.sku||"",
      price:selectedDetailPrice,
      oldPrice:selectedDetailMrp,
      stock:selectedDetailStock,
      image:selectedDetailImages[0]||selectedProduct.image||"",
      customMeasurements: selectedProductSize === "Custom" ? (customMeasurements.trim() || fitMeasurementText) : "",
      fitSizeResult: fitSizeResult || "",
      fitPhotoPermission: Boolean(fitPhoto),
    };
    addToCart(configuredProduct, productQuantity);
    setProductDetailOpen(false);
  };

  const buySelectedProductNow = () => {
    if (!selectedProduct) return;
    const configuredProduct = {
      ...selectedProduct,
      selectedSize: selectedProductSize,
      selectedColor: selectedProductColor,
      selectedVariantId:selectedLiveVariant?.id||null,
      selectedVariantSku:selectedLiveVariant?.sku||selectedProduct.sku||"",
      price:selectedDetailPrice,
      oldPrice:selectedDetailMrp,
      stock:selectedDetailStock,
      image:selectedDetailImages[0]||selectedProduct.image||"",
      customMeasurements: selectedProductSize === "Custom" ? customMeasurements : "",
    };
    buyNow(configuredProduct, productQuantity);
    setProductDetailOpen(false);
  };

  const updateCartQuantity = (productKeyOrName, change) => {
    setCart((current) =>
      current
        .map((item) =>
          (item.cartKey||item.name) === productKeyOrName
            ? { ...item, quantity: (item.quantity || 1) + change }
            : item
        )
        .filter((item) => (item.quantity || 0) > 0)
    );
  };

  const removeFromCart = (productName) => {
    setCart((current) =>
      current.filter((item) => item.name !== productName)
    );
  };

  const cartCount = cart.reduce(
    (total, item) => total + (item.quantity || 1),
    0
  );

  const cartSubtotal = cart.reduce((total, item) => {
    const price =
      Number(String(item.price || "").replace(/[^0-9.]/g, "")) || 0;
    return total + price * (item.quantity || 1);
  }, 0);

  // ============================================================
  // SMART CART OFFER ENGINE — Cart/Checkout scope only
  // Buy 2 → 5% off | Buy 3 → 10% off | Buy 4+ → cheapest unit free
  // ============================================================
  const cartPromotion = (() => {
    const units = cart.reduce((sum, item) => sum + Math.max(1, Number(item?.quantity) || 1), 0);
    const unitPrices = cart.flatMap((item) => {
      const price = Number(String(item?.price || item?.offerPrice || "").replace(/[^0-9.]/g, "")) || 0;
      return Array(Math.max(1, Number(item?.quantity) || 1)).fill(price);
    }).filter((price) => price > 0).sort((a, b) => a - b);

    if (units >= 4 && unitPrices.length >= 4) {
      return {
        tier: "FREE_ITEM",
        discount: Math.round(unitPrices[0]),
        label: "Buy 3, get the 4th item FREE",
        message: "🎁 You unlocked a FREE item — your lowest-priced eligible item is free.",
        next: null,
      };
    }

    if (units === 3) {
      return {
        tier: "THREE",
        discount: Math.round(cartSubtotal * 0.10),
        label: "Buy 3 → extra 10% OFF",
        message: "🔥 3 items unlocked 10% OFF. Add 1 more item to unlock a FREE item.",
        next: 1,
      };
    }

    if (units === 2) {
      return {
        tier: "TWO",
        discount: Math.round(cartSubtotal * 0.05),
        label: "Buy 2 → extra 5% OFF",
        message: "✨ 2 items unlocked extra 5% OFF. Add 1 more item for 10% OFF.",
        next: 1,
      };
    }

    return {
      tier: "ONE",
      discount: 0,
      label: "Add 1 more item → unlock 5% OFF",
      message: "💡 Add 1 more item to unlock extra 5% OFF.",
      next: 1,
    };
  })();

  const checkoutCouponDiscount = checkoutCouponApplied ? Math.min(Math.round(cartSubtotal * 0.10), 500) : 0;
  const checkoutDiscount = Math.max(0, cartPromotion.discount + checkoutCouponDiscount);
  const checkoutGiftWrap = giftWrap ? 49 : 0;
  const checkoutDelivery = cartSubtotal - checkoutDiscount >= 999 ? 0 : 49;
  const checkoutTotal = Math.max(0, cartSubtotal - checkoutDiscount + checkoutDelivery + checkoutGiftWrap);
  const checkoutServerSubtotal=Number(checkoutQuote?.subtotal??cartSubtotal);
  const checkoutServerDiscount=Number(checkoutQuote?.discountTotal??checkoutDiscount);
  const checkoutServerDelivery=Number(checkoutQuote?.shippingTotal??checkoutDelivery);
  const checkoutServerTax=Number(checkoutQuote?.taxTotal??checkoutTax);
  const checkoutServerTotal=Number(checkoutQuote?.grandTotal??checkoutTotal);


  const cartRecommendations = getCartRecommendations(cart, products, {
    customerId: currentUser?.id,
    location: customerLocation,
    wishlist,
    recentlyViewed,
  }).slice(0, 4);

  const recommendationBudget = cartPromotion.tier === "ONE"
    ? 1500
    : cartPromotion.tier === "TWO"
      ? 1800
      : 2500;


  const applyCartCoupon = () => {
    const code = cartCoupon.trim().toUpperCase();
    if (code === "HOWDI10") {
      setCartCouponApplied(true);
      setCartNotice("🎉 HOWDI10 applied — 10% demo discount added.");
    } else {
      setCartCouponApplied(false);
      setCartNotice(code ? "Coupon not available in this frontend demo." : "Enter a coupon code first.");
    }
  };

  const checkCartPincode = () => {
    const value = cartPincode.replace(/\D/g, "").slice(0, 6);
    setCartPincode(value);
    setCartPincodeChecked(value.length === 6);
    setCartNotice(value.length === 6
      ? "📦 Delivery estimate checked. Final promise will come from the backend later."
      : "Please enter a valid 6-digit pincode.");
  };

  const openCheckout = () => {
    if (!cart.length) return;
    if (!currentUser) {
      openLogin();
      return;
    }
    const defaultAddress = addresses.find((item) => item.is_default) || addresses[0] || null;
    setSelectedCheckoutAddress(defaultAddress);
    setCheckoutStep(defaultAddress ? 2 : 1);
    setCheckoutPayment(paymentMethods.length ? "SAVED" : "COD");
    setCheckoutCoupon("");
    setCheckoutCouponApplied(false);
    setCheckoutQuote(null);
    setCheckoutQuoteToken("");
    setCheckoutQuoteExpiresAt("");
    checkoutIdempotencyRef.current=(globalThis.crypto?.randomUUID?.()||`checkout-${Date.now()}-${Math.random().toString(36).slice(2)}`);
    setCheckoutQuoteError("");
    setCheckoutPaymentState(null);
    setCheckoutMessage("");
    setOrderSuccess(null);
    setCartOpen(false);
    setCheckoutOpen(true);
  };

  const checkoutQuotePayload=(couponOverride=checkoutCoupon)=>({
    address_id:selectedCheckoutAddress?.id||null,
    coupon_code:String(couponOverride||"").trim().toUpperCase()||null,
    items:cart.map(item=>({product_id:item.id??item.product_id??"",variant_id:item.selectedVariantId??item.variantId??null,quantity:Number(item.quantity||1)}))
  });
  const refreshCheckoutQuote=async(couponOverride=checkoutCoupon,{quiet=false}={})=>{
    if(!currentUser||!cart.length||!selectedCheckoutAddress)return null;
    setCheckoutQuoteBusy(true);setCheckoutQuoteError("");
    try{
      const response=await fetch(`${API_BASE}/api/orders/pricing-quote`,{method:"POST",headers:{"Content-Type":"application/json",...customerSessionHeaders()},
        body:JSON.stringify(checkoutQuotePayload(couponOverride))});
      const data=await response.json().catch(()=>({}));if(!response.ok||data.status!=="success")throw new Error(data.message||"Unable to calculate checkout price");
      setCheckoutQuote(data.pricing||null);setCheckoutQuoteToken(data.quote_token||"");setCheckoutQuoteExpiresAt(data.expires_at||"");
      const applied=Boolean(data.pricing?.coupon?.applied);setCheckoutCouponApplied(applied);
      if(!quiet)setCheckoutMessage(applied?`🎉 ${data.pricing.coupon.code} applied by HOWDI server.`:
        (String(couponOverride||"").trim()?`Coupon not applied: ${String(data.pricing?.coupon?.reason||"not eligible").replaceAll("_"," ").toLowerCase()}`:"Price refreshed from HOWDI server."));
      return data.pricing||null;
    }catch(e){setCheckoutQuote(null);setCheckoutQuoteToken("");setCheckoutQuoteExpiresAt("");setCheckoutCouponApplied(false);setCheckoutQuoteError(e.message||"Unable to calculate price");if(!quiet)setCheckoutMessage(e.message||"Unable to calculate price");return null}
    finally{setCheckoutQuoteBusy(false)}
  };
  const applyCheckoutCoupon=()=>refreshCheckoutQuote(checkoutCoupon);


  const placeCheckoutOrder = async () => {
    if (placingOrder) return;
    if (!cart.length) {
      setCheckoutMessage("Your cart is empty.");
      return;
    }

    if (!currentUser?.id) {
      setCheckoutMessage("Please login again before placing the order.");
      openLogin();
      return;
    }

    if (!selectedCheckoutAddress) {
      setCheckoutStep(1);
      setCheckoutMessage("Please select or add a delivery address.");
      return;
    }

    const pin = String(selectedCheckoutAddress.pincode || "").replace(/\D/g, "");
    if (!/^[1-9][0-9]{5}$/.test(pin)) {
      setCheckoutStep(1);
      setCheckoutMessage("Please select an address with a valid 6-digit pincode.");
      return;
    }

    if (!checkoutPayment) {
      setCheckoutStep(2);
      setCheckoutMessage("Please select a payment method.");
      return;
    }

    const authoritativeQuote=await refreshCheckoutQuote(checkoutCoupon,{quiet:true});
    if(!authoritativeQuote){setCheckoutMessage("Unable to verify the latest server price. Please retry.");return;}
    const orderNumber = `HD${String(Date.now()).slice(-8)}`;
    const trackingNumber = `HOWDI${String(Date.now()).slice(-10)}`;
    const walletUsed = Math.round(Number(checkoutWalletCredit) || 0);
    const rewardsUsed = Math.round(Number(checkoutRewardsCredit) || 0);
    const rewardPointsUsed = rewardsUsed * 10;

    const orderPayload = {
      user_id: currentUser.id,
      customer_id: currentUser.id,
      vibe_checkout_token: vibeDirectCheckoutToken || null,
      address_id: selectedCheckoutAddress?.id || null,
      order_number: orderNumber,
      title: cart.length === 1
        ? cart[0]?.name || "HOWDI Order"
        : `${cart[0]?.name || "HOWDI"} + ${cart.length - 1} more`,
      shop: cart[0]?.shop || "HOWDI Marketplace",
      total: `₹${checkoutTotal.toLocaleString("en-IN")}`,
      amount: Number(checkoutTotal) || 0,
      subtotal: Number(cartSubtotal) || 0,
      discount_total: Number(checkoutDiscount) || 0,
      shipping_total: Number(checkoutDelivery) || 0,
      tax_total: Number(checkoutTax) || 0,
      grand_total: Number(checkoutTotal) || 0,
      currency: "INR",
      discount: Number(checkoutDiscount) || 0,
      smart_cart_discount: Number(cartPromotion.discount) || 0,
      coupon_discount: Number(checkoutCouponDiscount) || 0,
      coupon_code: checkoutCouponApplied ? checkoutCoupon.trim().toUpperCase() : null,
      quote_token: checkoutQuoteToken,
      delivery_charge: Number(checkoutDelivery) || 0,
      gift_wrap: Boolean(giftWrap),
      gift_wrap_charge: Number(checkoutGiftWrap) || 0,
      gift_message: giftWrap && giftMessageSaved ? giftMessage.trim() : "",
      tax: Number(checkoutTax) || 0,
      wallet_used: walletUsed,
      rewards_used: rewardPointsUsed,
      item_count: cart.reduce((sum, item) => sum + (Number(item?.quantity) || 1), 0),
      items: cart.map((item)=>({
        product_id:item.id??item.product_id??"",
        variant_id:item.selectedVariantId??item.variantId??null,
        product_name:item.name||"HOWDI Product",
        sku:item.selectedVariantSku||item.sku||"",
        image_url:item.image||item.imageUrls?.[0]||"",
        selected_colour:item.selectedColor||item.color||"",
        selected_size:item.selectedSize||item.size||"",
        variant_name:[item.selectedColor||item.color,item.selectedSize||item.size].filter(Boolean).join(" / "),
        quantity:Number(item.quantity||1),
        // Live products are repriced by the backend from PostgreSQL.
        // numericPrice is retained only for legacy/demo catalogue compatibility.
        numericPrice:Number(item.numericPrice||0),
        unit_price:Number(item.numericPrice||0),
        vibe_attribution:item.vibeAttribution||item.vibe_attribution||null
      })),
      status: "PLACED",
      payment_method: checkoutPayment,
      payment_status: "pending",
      delivery_option: checkoutDeliveryOption,
      address: selectedCheckoutAddress,
      estimated_delivery: checkoutDeliveryOption === "EXPRESS" ? "1–3 days" : "3–6 days",
      tracking_number: trackingNumber,
      coupon: checkoutCouponApplied ? checkoutCoupon.trim().toUpperCase() : "",
      maker_note: "Your piece will receive a final handmade quality check before dispatch.",
    };

    try {
      setPlacingOrder(true);
      setCheckoutMessage("Creating your HOWDI order...");

      const response = await fetch(`${API_BASE}/api/orders`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Idempotency-Key": checkoutIdempotencyRef.current || (checkoutIdempotencyRef.current=`checkout-${Date.now()}-${Math.random().toString(36).slice(2)}`),
          ...customerSessionHeaders(),
        },
        body: JSON.stringify(orderPayload),
      });

      const data = await response.json().catch(() => ({}));

      if (!response.ok || data.status !== "success") {
        if(data.code==="QUOTE_CHANGED"&&data.requires_requote){
          if(data.refreshed_pricing)setCheckoutQuote(data.refreshed_pricing);
          await refreshCheckoutQuote(checkoutCoupon,{quiet:true});
          setCheckoutMessage("Checkout price changed. Please review the refreshed campaign, coupon, tax, shipping and final total, then place the order again.");
          return;
        }
        throw new Error(data.message || `Unable to create order (HTTP ${response.status}).`);
      }

      const createdOrder = normalizeCustomerOrder(data.order || {
        ...orderPayload,
        id: `local_${Date.now()}`,
        order_id: `HOWDI-${Date.now()}`,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      });
      setCheckoutPaymentState(data.payment||null);

      if (vibeDirectCheckoutToken) setVibeDirectCheckoutToken(null);

      // Update wallet/rewards only after the backend has successfully created the order.
      if (walletUsed > 0) {
        setWalletBalance((current) =>
          Math.max(0, Number(current || 0) - walletUsed)
        );
        setWalletTransactions((current) => [
          {
            id: Date.now(),
            title: `Order ${createdOrder.order_number || orderNumber}`,
            type: "debit",
            amount: walletUsed,
            date: new Date().toLocaleDateString("en-IN"),
          },
          ...current,
        ]);
      }

      if (rewardPointsUsed > 0) {
        setRewardPoints((current) =>
          Math.max(0, Number(current || 0) - rewardPointsUsed)
        );
        setWalletRewards((current) => [
          {
            id: Date.now() + 1,
            title: `Used for order ${createdOrder.order_number || orderNumber}`,
            points: -rewardPointsUsed,
            date: new Date().toLocaleDateString("en-IN"),
          },
          ...current,
        ]);
      }

      setOrders((current) => [
        createdOrder,
        ...current.filter(
          (order) => String(order.id || order.order_id) !== String(createdOrder.id)
        ),
      ]);

      // Keep a local cache for graceful UI fallback, but backend is the source of truth.
      try {
        const cached = [
          createdOrder,
          ...orders.filter(
            (order) => String(order.id || order.order_id) !== String(createdOrder.id)
          ),
        ];
        localStorage.setItem(
          `howdiOrders_${currentUser.id}`,
          JSON.stringify(cached)
        );
      } catch {}

      // 🧠 Record a purchase-strength signal only when the order is commercially confirmed.
      if(data.payment?.confirmation_state==="CONFIRMED_COD"||data.payment?.confirmation_state==="CONFIRMED_PAID") cart.forEach((item) => {
        recordTasteEvent({
          type: "purchase",
          customerId: currentUser.id,
          productId: item.id ?? item.product_id ?? item._id ?? item.name,
          name: item.name,
          category: item.category,
          subcategory: item.subcategory,
          color: item.color ?? item.colors?.[0],
          shop: item.shop,
          price: item.price ?? item.offerPrice,
          location: selectedCheckoutAddress?.city || customerLocation,
          weight: Math.max(1, Number(item.quantity) || 1),
        });
      });

      setCart([]);
      localStorage.setItem("howdiCart", "[]");
      setCheckoutOpen(false);
      setCheckoutMessage("");
      setOrderSuccess(createdOrder);
      await loadCustomerOrders().catch(()=>{});
    } catch (error) {
      console.error("HOWDI CREATE ORDER ERROR:", error);
      setCheckoutMessage(
        error?.message ||
        "Unable to place the order. Please try again."
      );
    } finally {
      setPlacingOrder(false);
    }
  };


