  const [loginLoading, setLoginLoading] = useState(false);
  const [loginMessage, setLoginMessage] = useState("");

  // HOWDI V16.6H — My HOWDI ↔ Learn & Earn session bridge.
  useEffect(() => {
    const storedUserId = currentUser?.id || currentUser?.user_id;
    if (!storedUserId) return;
    let cancelled = false;
    (async () => {
      const token = localStorage.getItem("howdiSessionToken") || "";
      if (!token) {
        if (cancelled) return;
        localStorage.removeItem("howdiUser");
        setCurrentUser(null);
        setLoginMessage("Your HOWDI session needs to be refreshed. Please sign in again.");
        return;
      }
      try {
        const response = await fetch(`http://localhost:5000/api/profile/${encodeURIComponent(storedUserId)}`, {
          cache: "no-store",
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok || data.status !== "success" || !data.user) {
          if (response.status === 401 || response.status === 403) throw new Error("SESSION_EXPIRED");
          return;
        }
        if (cancelled) return;
        const hydrated = { ...currentUser, ...data.user, id:data.user.id };
        setCurrentUser(hydrated);
        localStorage.setItem("howdiUser", JSON.stringify(hydrated));
        setNotificationPreferencesNotice("");
        setProfileNotice("");
        setLearningNotice("");
        setLearnerHomeNotice("");
        setCoursePurchaseNotice("");
      } catch (error) {
        if (cancelled || error?.message !== "SESSION_EXPIRED") return;
        localStorage.removeItem("howdiSessionToken");
        localStorage.removeItem("howdiUser");
        setCurrentUser(null);
        setLoginMessage("Your previous HOWDI session expired. Please sign in again.");
      }
    })();
    return () => { cancelled = true; };
  }, [currentUser?.id, currentUser?.user_id]);

  const [backendStatus, setBackendStatus] = useState("Checking...");

