  const openNavigationOSArea=(area,subview="home")=>{
    const next=String(area||"connect").toLowerCase();
    const view=String(subview||"home").toLowerCase();

    closeHeaderPanels();
    setMenuOpen(false);
    setNavDropdown(null);
    setConnectExpanded(false);
    setMyHowdiDrawer(null);
    setProfileOpen(false);

    // R10 invariant: exactly ONE active pillar workspace.
    setNavigationOSArea(next);
    setConnectModalOpen(false);
    setWorksExperienceOpen(false);
    setLearningBrowseOpen(false);

    if(next==="home"){
      setActiveSection("home");
      setSlideIndex(0);
      window.setTimeout(()=>document.querySelector(".howdi-os-home")?.scrollTo({top:0}),0);
      return;
    }
    if(next==="connect"){
      const connectTarget=view==="vibe"||view==="home"?"feed":view==="explore"?"discover":view;
      setConnectView(connectTarget);
      setConnectContentMode(view==="vibe"?"vibe":"posts");
      setConnectModalOpen(true);
      return;
    }
    if(next==="shop"){
      setActiveSection("shop");
      setShopOSView(view==="home"?"home":view);
      if(view==="cart"){
        setCartToast(null);setCartOpen(true);
      }else if(view==="categories"){
        window.setTimeout(()=>document.querySelector(".hs2-categories")?.scrollIntoView({behavior:"smooth",block:"start"}),60);
      }else if(view==="discovery"){
        window.setTimeout(()=>document.querySelector("#howdi-buy-products")?.scrollIntoView({behavior:"smooth",block:"start"}),60);
      }else if(view==="vendor"){
        setApplyNotice("");setApplySuccess(null);setApplyStep(1);setHowdiApplyType("vendor");
      }else if(view==="home"){
        window.setTimeout(()=>window.scrollTo({top:0,behavior:"smooth"}),40);
      }
      return;
    }
    if(next==="works"){
      setWorksExperienceTab(view==="home"?"home":view);
      setWorksExperienceOpen(true);
      return;
    }
    if(next==="learn"){
      setLearningPortalView(view);
      setLearningBrowseOpen(true);
      if(currentUser?.id||currentUser?.user_id)loadLearnerHome();
      return;
    }
    if(next==="hpay"){
      // HPay is a global utility rendered inside the shared HOWDI shell.
      // Keep the Connect shell mounted so the HPay workspace is actually visible.
      setNavigationOSArea("connect");
      setConnectView("hpay");
      setConnectContentMode("posts");
      setConnectModalOpen(true);
      return;
    }
  };

  const navigate = (section) => {
    if (["home", "connect", "shop", "works", "learn"].includes(section)) {
      openNavigationOSArea(section, section === "works" ? "find" : section === "learn" ? "discover" : "home");
      return;
    }
    openNavigationOSArea("home");
    closeHeaderPanels();
    setConnectExpanded(false);
    setActiveSection(section);
    setMenuOpen(false);

    setTimeout(() => {
      const target =
        document.getElementById(section);

      target?.scrollIntoView({
        behavior: "smooth",
      });
    }, 50);
  };

  // ==============================
