  // Revoke this server session before clearing local identity. Reload also clears
  // mounted account data and pending UI state before another customer signs in.
  const handleLogout = async () => {
    if (logoutBusy) return;
    setLogoutBusy(true);
    setLogoutNotice("");
    try {
      const token = localStorage.getItem("howdiSessionToken");
      if (token) {
        const response = await fetch(`${SHOP_API_BASE}/api/auth/logout`, {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
          signal: AbortSignal.timeout(10000),
        });
        if (!response.ok && response.status !== 401) {
          const data = await response.json().catch(() => ({}));
          throw new Error(data.message || "Unable to sign out. Please try again.");
        }
      }
      localStorage.removeItem("howdiSessionToken");
      localStorage.removeItem("howdiUser");
      setCurrentUser(null);
      setMyHowdiDrawer(null);
      setAccountMenuOpen(false);
      window.location.reload();
    } catch (error) {
      setLogoutNotice(error.name === "TimeoutError" ? "Sign out timed out. Please try again." : "Sign out could not be completed. Check your connection and try again.");
    } finally {
      setLogoutBusy(false);
    }
  };

