const saveProfileDetails = async (event) => {
  event?.preventDefault();

  if (!currentUser?.id) {
    setProfileNotice(
      "Please login again to update your profile."
    );
    return;
  }

  const full_name =
    String(profileForm.full_name || "").trim();

  const email =
    String(
      profileForm.email ||
      currentUser.email ||
      ""
    )
      .trim()
      .toLowerCase();

  const phone =
    String(profileForm.phone || "")
      .replace(/\D/g, "")
      .slice(0, 10);

  const public_username = String(profileForm.public_username || "")
    .trim()
    .toLowerCase()
    .replace(/^@+/, "");

  // VALIDATION

  if (!full_name) {
    setProfileNotice(
      "Please enter your full name."
    );
    return;
  }

  if (!email) {
    setProfileNotice(
      "Please enter your email address."
    );
    return;
  }

  if (!/^\S+@\S+\.\S+$/.test(email)) {
    setProfileNotice(
      "Please enter a valid email address."
    );
    return;
  }

  if (phone.length !== 10) {
    setProfileNotice(
      "Please enter a valid 10-digit mobile number."
    );
    return;
  }

  if (public_username && !/^[a-z0-9._]{3,30}$/.test(public_username)) {
    setProfileNotice("Public username must be 3–30 characters using letters, numbers, dot or underscore.");
    return;
  }

  try {
    setProfileNotice(
      "Saving profile..."
    );

    const response =
      await fetch(
        `http://localhost:5000/api/profile/${encodeURIComponent(
          currentUser.id
        )}`,
        {
          method: "PUT",

          headers: {
            "Content-Type":
              "application/json",
            ...customerSessionHeaders(),
          },

          body: JSON.stringify({
            full_name,
            email,
            phone,
            public_username,
          }),
        }
      );

    const data =
      await response.json();

    if (
      !response.ok ||
      data.status !== "success" ||
      !data.user
    ) {
      throw new Error(
        data.message ||
        "Unable to update profile."
      );
    }

    const savedPublicUsername = data.user.public_username || public_username || null;

    const updatedUser = {
      ...currentUser,
      ...data.user,
      ...(savedPublicUsername ? { public_username: savedPublicUsername } : {}),

      name:
        data.user.full_name,

      profile_status:
        profileStatus,

      profile_image:
        profileAvatar,
    };

    setCurrentUser(updatedUser);
    if (savedPublicUsername) {
      setProfileForm(v => ({...v, public_username:savedPublicUsername}));
      setConnectSocialSettings(v => ({...v, publicUsername: savedPublicUsername}));
      setConnectBootstrap(v => ({...v, profile:{...(v?.profile||{}), public_username:savedPublicUsername}}));
      setConnectSocialSummary(v => v ? ({...v, profile:{...(v.profile||{}), public_username:savedPublicUsername}}) : v);
    }

    localStorage.setItem(
      "howdiUser",
      JSON.stringify(updatedUser)
    );

    saveProfileMedia(
      profileAvatar,
      profileStatus
    );

    setProfileEditOpen(false);

    setProfileNotice(
      "Profile details saved successfully. ✓"
    );

  } catch (error) {
    console.error(
      "HOWDI PROFILE UPDATE ERROR:",
      error
    );

    setProfileNotice(
      error.message ||
      "Unable to update profile. Please try again."
    );
  }
};

  
