  const saveAddress = async (event) => {
    event.preventDefault();

    if (!currentUser?.id) {
      setAddressNotice("Please login again before saving an address.");
      return;
    }

    const pincode = String(addressForm.pincode ?? "").replace(/\D/g, "").slice(0, 6);
    if (pincode.length !== 6) {
      setAddressNotice("Please enter a valid 6-digit pincode.");
      return;
    }

    if (
      !addressForm.full_name.trim() ||
      !addressForm.phone.trim() ||
      !addressForm.address_line1.trim() ||
      !addressForm.city.trim() ||
      !addressForm.state.trim()
    ) {
      setAddressNotice("Please complete all required address fields.");
      return;
    }

    const payload = {
      user_id: currentUser.id,
      label: addressForm.label.trim() || "Other",
      full_name: addressForm.full_name.trim(),
      phone: addressForm.phone.trim(),
      address_line1: addressForm.address_line1.trim(),
      address_line2: addressForm.address_line2.trim(),
      landmark: addressForm.landmark?.trim() || "",
      city: addressForm.city.trim(),
      state: addressForm.state.trim(),
      pincode,
      country: addressForm.country || "India",
      address_type: addressForm.address_type || "HOME",
      is_default: Boolean(addressForm.is_default),
    };

    setAddressLoading(true);
    setAddressNotice("");

    try {
      const endpoint = editingAddressId
        ? `http://localhost:5000/api/addresses/${encodeURIComponent(editingAddressId)}`
        : "http://localhost:5000/api/addresses";

      const response = await fetch(endpoint, {
        method: editingAddressId ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to save address");
      }

      setAddressFormOpen(false);
      setEditingAddressId(null);
      setAddressForm({
        label: "Home",
        full_name: "",
        phone: "",
        address_line1: "",
        address_line2: "",
        landmark: "",
        city: "",
        state: "",
        pincode: "",
        country: "India",
        address_type: "HOME",
        is_default: false,
      });
      setAddressNotice(data.message || "Address saved successfully.");
      await loadAddresses();
    } catch (error) {
      console.error("Address save error:", error);
      setAddressNotice(error.message || "Unable to save address.");
    } finally {
      setAddressLoading(false);
    }
  };

