                              <button
                                type="button"
                                onClick={() => deleteAddress(address.id)} disabled={addressLoading}
                                style={{
                                  border: "1px solid #fecaca",
                                  background: "#fff",
                                  color: "#b91c1c",
                                  borderRadius: "10px",
                                  padding: "8px 12px",
                                  fontWeight: 700,
                                  cursor: "pointer",
                                }}
                              >
                                Delete
                              </button>

