                    {connectGCLoading?<div className="hc2-empty">Loading groups…</div>:<div className="hc160b-space-grid">{connectGCSpaces.map(space=><article key={space.id}><div className="hc160b-space-icon">👥</div><div className="hc160b-space-copy"><div><b>{space.name}</b>{space.is_verified&&<em>✓</em>}</div><small>{space.description||"HOWDI group"}</small><span>{space.member_count||0} members · {String(space.privacy||"PUBLIC").replaceAll("_"," ")}</span></div><div className="hc160b-space-actions"><button onClick={()=>openConnectGCSpace(space)}>Open</button><button className={space.joined?"joined":"primary"} onClick={()=>toggleConnectGCMembership(space)}>{space.joined?"Joined ✓":space.membership_status==="PENDING"?"Requested":"Join"}</button>{["OWNER","ADMIN","MODERATOR"].includes(space.membership_role)&&<button onClick={()=>createConnectGCInvite(space)}>🔗 Invite</button>}</div></article>)}</div>}
