          {connectCommunityIntelTab==="experts"&&<section><div className="hc133-section-head"><h3>Trust-ranked contributors</h3><span>Based on useful knowledge + Teach Backs + contribution</span></div><div className="hc133-expert-grid">{(connectCommunityIntel.experts||[]).map((x,i)=><article key={x.id}><em>#{i+1}</em><b>{x.full_name}</b><small>{x.public_username?`@${x.public_username}`:"HOWDI member"} · Trust {x.trust_score}</small><div><span>👍 {x.useful_votes}</span><span>🗣 {x.teachbacks}</span><span>📝 {x.posts}</span></div></article>)}</div></section>}
