                  <section><small>TOP SUPPORTERS</small><h4>Community support</h4>{(connectSpaceAnalytics.top_supporters||[]).length?<div className="hc94-supporters">{connectSpaceAnalytics.top_supporters.map((s,i)=><div key={s.user_id}><i>{i+1}</i><span><b>{s.full_name}</b><small>{s.tip_count} tips</small></span><strong>₹{Number(s.tip_total||0).toLocaleString("en-IN")}</strong></div>)}</div>:<p className="hc94-no-data">No completed supporter tips yet.</p>}</section>
