// ============================================================================
// HOWDI V16.6E — FRONTEND COMPILE/API WIRING + BLANK-SCREEN PREVENTION
// ============================================================================

export class HowdiAppErrorBoundaryV166E extends Component {
  constructor(props){
    super(props);
    this.state={hasError:false,error:null};
  }
  static getDerivedStateFromError(error){
    return {hasError:true,error};
  }
  componentDidCatch(error,info){
    console.error("[HOWDI V16.6E] UI render failure",error,info);
  }
  render(){
    if(this.state.hasError){
      return (
        <main className="howdi166e-crash-shell" role="alert">
          <section className="howdi166e-crash-card">
            <div className="howdi166e-crash-mark">HOWDI</div>
            <h1>We couldn't open this screen.</h1>
            <p>Your HOWDI account is safe. Refresh this page to retry.</p>
            <button type="button" onClick={()=>window.location.reload()}>Refresh HOWDI</button>
            <details>
              <summary>Technical details</summary>
              <code>{String(this.state.error?.message||"Unknown render error")}</code>
            </details>
          </section>
        </main>
      );
    }
    return this.props.children;
  }
}

export async function howdiFrontendBootCheckV166E(){
  const started=Date.now();
  try{
    const r=await fetch("/api/platform/v166e/frontend-health",{
      method:"GET",headers:{"Accept":"application/json"}
    });
    const type=String(r.headers.get("content-type")||"");
    if(!r.ok) throw new Error(`HOWDI API health failed (${r.status})`);
    if(!type.includes("application/json")) throw new Error("HOWDI API returned a non-JSON health response");
    const data=await r.json();
    return {ok:true,latencyMs:Date.now()-started,data};
  }catch(error){
    return {ok:false,latencyMs:Date.now()-started,error:String(error?.message||error)};
  }
}

