// ============================================================================
// HOWDI V16.6F — API CONTRACT + FETCH RELIABILITY
// New/updated frontend flows should use howdiApiV166F instead of raw fetch.
// Legacy raw fetch calls remain compatible and can be migrated brick-by-brick.
// ============================================================================

export class HowdiApiErrorV166F extends Error{
  constructor(message,{status=0,code="API_ERROR",requestId=null,details=null}={}){
    super(message); this.name="HowdiApiErrorV166F";
    this.status=status; this.code=code; this.requestId=requestId; this.details=details;
  }
}

export async function howdiApiV166F(path,options={}){
  const method=String(options.method||"GET").toUpperCase();
  const timeoutMs=Number(options.timeoutMs||15000);
  const retries=Number(options.retries ?? ((method==="GET"||method==="HEAD")?1:0));
  let attempt=0,lastError=null;
  while(attempt<=retries){
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),timeoutMs);
    const started=Date.now();
    try{
      const headers={Accept:"application/json",...(options.headers||{})};
      let body=options.body;
      if(body && typeof body==="object" && !(body instanceof FormData)){
        headers["Content-Type"]=headers["Content-Type"]||"application/json";
        body=JSON.stringify(body);
      }
      const response=await fetch(path,{
        ...options,method,headers,body,signal:controller.signal,
        credentials:options.credentials||"same-origin"
      });
      const requestId=response.headers.get("x-request-id");
      const contentType=String(response.headers.get("content-type")||"");
      if(!contentType.includes("application/json")){
        throw new HowdiApiErrorV166F("HOWDI API returned a non-JSON response",
          {status:response.status,code:"NON_JSON_RESPONSE",requestId});
      }
      const payload=await response.json();
      if(!response.ok || payload?.ok===false){
        const err=payload?.error;
        throw new HowdiApiErrorV166F(
          typeof err==="object" ? (err.message||"HOWDI request failed") : (err||"HOWDI request failed"),
          {status:response.status,code:err?.code||"API_REQUEST_FAILED",
           requestId:payload?.requestId||requestId,details:err?.details||null}
        );
      }
      return {payload,status:response.status,requestId,durationMs:Date.now()-started};
    }catch(error){
      lastError=error?.name==="AbortError"
        ? new HowdiApiErrorV166F("HOWDI request timed out",{code:"REQUEST_TIMEOUT"})
        : error;
      if(attempt>=retries) throw lastError;
      await new Promise(r=>setTimeout(r,250*(attempt+1)));
    }finally{clearTimeout(timer);}
    attempt++;
  }
  throw lastError||new HowdiApiErrorV166F("HOWDI request failed");
}

