// HOWDI V16.6G — DATABASE PERFORMANCE + PAGINATION + CACHE FOUNDATION
export function howdiPageParamsV166G({limit=30,offset=0,cursor=null}={}){
  const safeLimit=Math.min(100,Math.max(1,Number(limit)||30));
  const safeOffset=Math.max(0,Number(offset)||0);
  const q=new URLSearchParams({limit:String(safeLimit),offset:String(safeOffset)});
  if(cursor)q.set("cursor",String(cursor));
  return q.toString();
}
